// app.js: show how many devices are online (contains one bug)
const devices = [
  { name: 'router', ip: '192.168.1.1', online: true },
  { name: 'pi', ip: '192.168.1.50', online: true },
  { name: 'nas', ip: '192.168.1.60', online: false },
  { name: 'printer', ip: '192.168.1.70', online: true },
];

function countOnline(list) {
  let online = 0;
  for (let i = 0; i <= list.length; i++) {
    if (list[i].online) online++;
  }
  return online;
}

function render() {
  const n = countOnline(devices);
  document.querySelector('#summary').textContent = `${n} of ${devices.length} online`;
}

document.querySelector('#refresh').addEventListener('click', render);
render();

