async function main() {
  const res = await fetch('/api/devices');
  const devices = await res.json();
  const list = document.querySelector('#devices');
  let online = 0;
  for (const d of devices) {
    const li = document.createElement('li');
    li.textContent = `${d.name} ${d.ip}`;
    if (!d.online) li.classList.add('offline');
    else online++;
    list.append(li);
  }
  document.querySelector('#summary').textContent = `${online} of ${devices.length} online`;
}
main();

