  for (let attempt = 1; attempt <= 3; attempt++) {
    console.group(`attempt ${attempt}`);
    try {
      const res = await fetch('/api/flaky');
      console.log('status', res.status);
      if (res.ok) {
        console.log(JSON.stringify(await res.json()));
        return;
      }
    } finally {
      console.groupEnd();
    }
  }
  console.log('gave up');
}
main();

